"{0} kHz": "{0} кГц",
"{0} GB · {#1} modules": {"one": "{0} ГБ · {1} модуль", "few": "{0} ГБ · {1} модулі", "many": "{0} ГБ · {1} модулів", "other": "{0} ГБ · {1} модуля"},
"running a job": "виконує завдання",
