"his mode blends": "його бленди ладів",
"his genres, sung in his languages": "його жанри, заспівані його мовами",
"{0} (from the Suno style lists)": "{0} (зі списків стилів Suno)",
"Hip-hop and rap": "Хіп-хоп і реп",
"R&B and soul": "R&B і соул",
"Rock and alternative": "Рок і альтернатива",
