"Out of the list; its checkpoint stays in the Trainer's run {0} (the Trainer puts it back)": "Прибрано зі списку; його чекпоінт лишається в рані Тренера {0} (Тренер поверне його)",
"muted": "приглушено",
"Right-click: back in the run": "Правий клік: повернути в прогін",
"Its trigger word goes at the style’s end by itself when the song is made": "Його слово-тригер саме стане в кінець стилю, коли пісня твориться",
"{0}: its trigger word “{1}” goes at the style's end when the song is made.": "{0}: його слово-тригер «{1}» стане в кінець стилю, коли пісня твориться.",
"Style as tags": "Стиль тегами",
