"Remember the key": "Запам'ятати ключ",
"Remember the key in this browser. Otherwise it lives only until the page is closed. The page sends it to openrouter.ai and nowhere else: not to the studio, not into its settings file.": "Запам'ятати ключ у цьому браузері. Інакше він живе лише до закриття сторінки. Сторінка надсилає його тільки на openrouter.ai: ні в студію, ні в її файл налаштувань.",
"Any model of openrouter.ai/models, written provider/model. The field offers the list as you type; the quick picks fill it in.": "Будь-яка модель з openrouter.ai/models у вигляді провайдер/модель. Поле пропонує список під час набору; швидкі вибори заповнюють його.",
"The section order the model gives new lyrics. «Keep mine» leaves the lyrics' own order.": "Порядок розділів, який модель дає новому тексту. «Залишити мій» зберігає порядок самого тексту.",
"The draft's style as tags, the most important first, as an SD/SDXL prompt is written. «Into the form» chooses which of the two, the tags or the readable style, the draft puts in the Style field.": "Стиль чернетки тегами, найважливіше першим, як пишеться промпт SD/SDXL. «У форму» обирає, що з двох — теги чи читабельний стиль — чернетка покладе в поле стилю.",
"Your saved briefs, kept by the lab (every browser sees them): picking one puts it in the box above.": "Твої збережені запити, їх зберігає лабораторія (їх бачить будь-який браузер): вибраний стає в поле вище.",
"The writing room works on the song in the Creator: “{0}”.": "Кімната письма працює з піснею у Творці: «{0}».",
"The notebook has “{0}” open. Put it into the Creator and send the request on it?": "У блокноті відкрито «{0}». Покласти його у Творця й надіслати запит на ньому?",
"Put it in and send": "Покласти й надіслати",
"Send on the Creator's song": "Надіслати на пісні Творця",
"the song as words and knobs: style, lyrics, score and sound; Generate makes it, Takes keep it": "пісня словами й регуляторами: стиль, текст, партитура і звук; кнопка «Створити пісню» її творить, «Семпли» зберігають",
"the take in hand, heard and mended: spectrum, artifacts, stems, remaster, upscale, lyrics check": "семпл у руках, вислуханий і виправлений: спектр, артефакти, стеми, ремастер, апскейл, перевірка тексту",
