"Section “{0}” made and in hand: new takes land in it": "Розділ «{0}» створено, він у руках: нові семпли лягають у нього",
"Nothing sent: choose a workspace for the new takes first": "Нічого не надіслано: спершу вибери простір для нових семплів",
"Models auto unload": "Автовивантаження моделей",
"after {#0} h idle": "після {0} год простою",
"after {#0} min idle": "після {0} хв простою",
"after {#0} h {#1} min idle": "після {0} год {1} хв простою",
"15 s after a song": "через 15 с після пісні",
"Unload idle models after": "Вивантажувати моделі, що простоюють, через",
"How long the models stay in GPU memory with nothing to do: 15 minutes to 4 hours, by 15. Then the engine unloads them, and the next song loads them again.": "Скільки моделі лишаються в пам'яті GPU без діла: від 15 хвилин до 4 годин, кроком 15. Потім рушій їх вивантажує, і наступна пісня завантажує їх знову.",
"The models leave GPU memory 15 s after a song: time enough to send the next one while they are still loaded": "Моделі йдуть із пам'яті GPU через 15 с після пісні: вистачить часу надіслати наступну, поки вони ще завантажені",
