"Show in the Librarian": "Показати в Бібліотекарі",
"Show this take in the Librarian: its card found, in sight and flashed": "Показати цей семпл у Бібліотекарі: його картку знайдено, вона на виду й підсвічена",
"Pin in “{0}”": "Закріпити в «{0}»",
"Unpin from “{0}”": "Відкріпити з «{0}»",
