"Fine-tune": "Файнтюн",
"Sampler": "Семплер",
"Schedule": "Розклад",
"Guidance": "Guidance",
"How each step is taken. Euler: the plain step; Euler SDE: fresh noise each step (soft on Qwen without Lightning). ER-SDE: a stochastic solver of third order, one look a step. RES 2s and 3s: the refined exponential solver, two or three looks a step (ODE: without noise). Heun++: up to three looks a step. Exp Heun 2 x0: the exponential Heun, two looks (SDE: with noise). More looks: finer, and as many times longer": "Як виконується кожен крок. Euler: простий крок; Euler SDE: свіжий шум на кожному кроці (м'яко на Qwen без Lightning). ER-SDE: стохастичний розв'язувач третього порядку, один погляд на крок. RES 2s і 3s: уточнений експоненційний розв'язувач, два або три погляди на крок (ODE: без шуму). Heun++: до трьох поглядів на крок. Exp Heun 2 x0: експоненційний Heun, два погляди (SDE: із шумом). Більше поглядів — тонше й у стільки ж разів довше",
"How the steps are spread from the noise to the picture: Simple (the painter's own), Karras and Exponential (more steps near the end, for detail; with Lightning they can paint the subject twice), Beta and Beta 57 (more at both ends), KL optimal (Align Your Steps' spacing), SGM uniform (even in time), Bong tangent (two slopes, through the middle)": "Як кроки розподілено від шуму до картинки: Simple (рідне в художника), Karras і Exponential (більше кроків ближче до кінця, заради деталей; з Lightning можуть намалювати сюжет двічі), Beta і Beta 57 (більше на обох кінцях), KL optimal (розстановка Align Your Steps), SGM uniform (рівно за часом), Bong tangent (два схили, через середину)",
"Lightning's strength: 1.0 as its makers give it, lower for a fine-tune (0.55 with 12 steps)": "Сила Lightning: 1.0, як дають його автори, нижче для файнтюну (0.55 при 12 кроках)",
"Without Lightning: how closely the picture follows the prompt (true CFG, two passes a step); 4 is Qwen-Image's own": "Без Lightning: наскільки точно картинка йде за промптом (справжній CFG, два проходи на крок); 4 — рідне в Qwen-Image",
