"Live preview": "Живий перегляд",
"Each step of the painting over its place, from the noise to the picture: an eighth of its size, seen without the decoder, so it costs nothing. Off: the place waits for the picture": "Кожен крок малювання на місці картинки, від шуму до картинки: у восьму частину розміру, без декодера, тож нічого не коштує. Вимкнено: місце чекає на картинку",
"Add…": "Додати…",
