"Auto ({#0} GB found, its limit {#1} GB in Engine → GPUs: context {#2}, VAE tiles {#3})": "Авто (знайдено {#0} ГБ, межа {#1} ГБ у «Рушій → Відеокарти»: контекст {#2}, тайли VAE {#3})",
"Auto ({#0} GB found, its limit {#1} GB in Engine → GPUs: whole context, VAE tiles {#2})": "Авто (знайдено {#0} ГБ, межа {#1} ГБ у «Рушій → Відеокарти»: увесь контекст, тайли VAE {#2})",
"Auto ({#0} GB found, its limit {#1} GB in Engine → GPUs: too small for YuE2)": "Авто (знайдено {#0} ГБ, межа {#1} ГБ у «Рушій → Відеокарти»: замало для YuE2)",
"The most of the card’s memory the studio’s work may take, the rest left to what else runs on it (a laptop’s desktop and browser): Compute’s Auto plans the engine’s knobs for the studio card’s limit, and the lab gives a card a job only when it fits under its limit": "Найбільша частка пам'яті карти, яку може взяти студія, решта — тому, що ще на ній іде (стільниця і браузер ноутбука): «Авто» в «Обчисленнях» планує ручки рушія під межу студійної карти, а лабораторія дає карті завдання, лише якщо воно вміщається під її межею",
"Look for a new release": "Шукати новий реліз",
