"The log in a window of its own": "Журнал в окремому вікні",
"The log in a window of its own: over every window where the browser can (Chrome), else one to carry to another monitor": "Журнал в окремому вікні: поверх усіх вікон, де браузер це вміє (Chrome), інакше — вікно, яке можна віднести на інший монітор",
"The server's log: the engine and the lab": "Журнал сервера: рушій і лабораторія",
"The Artist's own log: what was asked, what the lab answered, each run's way to its end; kept in this browser": "Власний журнал Художника: що просили, що відповіла лабораторія, шлях кожного рану до кінця; зберігається в цьому браузері",
"Which log": "Який журнал",
