// HERESY 1169 · 1339: the second look: the art's trash, the steps' help, the decode tips' lines, a few toasts
RuachI18n.add("uk", {
"Trash (Art)": "Кошик (Арт)",
"How many steps the sound solver takes to turn the music tokens into audio (flow matching, midpoint method). 32 is the release setting; 160 is the ceiling.": "Скільки кроків проходить звуковий розв'язувач, перетворюючи музичні токени на аудіо (flow matching, метод середньої точки). 32 — налаштування релізу; 160 — стеля.",
"Each step runs the sound model twice over the whole song, so 64 steps make this stage take twice as long as 32; the music itself (melody, words, length) is already fixed by then and does not change.": "Кожен крок двічі проганяє звукову модель по всій пісні, тож з 64 кроками ця стадія вдвічі довша, ніж з 32; сама музика (мелодія, слова, довжина) на той час уже зафіксована й не змінюється.",
"Fewer steps (8–16) are quicker drafts. Whether 64 sounds better than 32 has not been published: to hear it, re-render one take's sound at both settings.": "Менше кроків (8–16) — швидкі чернетки. Чи звучить 64 краще за 32, не публікувалося: щоб почути, відрендер звук одного семплу на обох налаштуваннях.",
"Decode this take again with this VAE: its own sound, another decoder, in seconds": "Декодувати цей семпл наново цим VAE: його власний звук, інший декодер, за секунди",
"Render this take's sound again with this VAE: it was made before takes kept their latents, so it takes as long as its sound did": "Відрендерити звук цього семплу наново цим VAE: його створено до того, як семпли почали зберігати латенти, тож це займе стільки ж, скільки його звук",
"Play this version": "Грати цю версію",
"This version": "Ця версія",
"same music, another grain": "та сама музика, інше зерно",
"Sound seed {#0}": "Звуковий сід {#0}",
"Creating the ABC score for {0}": "Створюю ABC-партитуру для {0}",
"not found": "не знайдено",
"A woman sings the lines that follow; the examples write only Male Vocals": "Рядки далі співає жінка; приклади пишуть лише Male Vocals",
"A pause in the singing while the music goes on": "Пауза в співі, поки музика йде далі",
"The voice and the music stop for a moment": "Голос і музика на мить замовкають",
"Instrumental, … no vocals, no singing, no choir, no spoken words": "Instrumental, … no vocals, no singing, no choir, no spoken words"
});
// HERESY 1169 · 1339: the cheat-sheet: its tabs and hints, the lyrics' tags and their notes, the phonetic hand, the styles' names
