"The clip's idea in a line or a few: what it is about, its mood, its story. The Writer writes the look and the scenes from it": "Задум кліпу в рядок чи кілька: про що він, його настрій, його історія. Письменник пише за ним вигляд і сцени",
"Reading what was made from this take…": "Читаю, що створено з цього семпла…",
"no like or dislike": "без лайка й дизлайка",
