"Upscale all": "Апскейл усіх",
"SeedVR2 7B sharp to 1080p for every shot that has a video and no upscale yet, dealt among the free cards; the clip takes each one as it comes": "SeedVR2 7B sharp у 1080p для кожного кадру з відео й ще без апскейлу, по вільних картах; кліп бере кожен, щойно прийде",
"Upscale all {0} shots that have a video with SeedVR2 7B sharp to 1080p?\n\nOn the free cards, about four minutes for a shot of four seconds; the clip takes each one as it comes. A shot's 🎬 menu has 1440p and the quick 3B.": "Апскейл усіх {0} кадрів з відео: SeedVR2 7B sharp у 1080p?\n\nНа вільних картах, близько чотирьох хвилин на кадр у чотири секунди; кліп бере кожен, щойно прийде. У меню 🎬 кадру є 1440p і швидка 3B.",
"{0} shot(s) to SeedVR2 on {1} card(s)": "{0} кадр(ів) у SeedVR2 на {1} карті(ах)",
"No shot with a video still to upscale": "Немає кадрів з відео, що чекають апскейлу",
"Upscale: {0}": "Апскейл: {0}",
"Upscale failed: {0}": "Апскейл не вдався: {0}",
"Upscaled by SeedVR2 to {0}p": "Апскейл SeedVR2 до {0}p",
"Videographer · SeedVR2 upscaler": "Відеограф · апскейлер SeedVR2",
"7B sharp": "7B sharp",
"the quick one: 18.6 GB of a card at 1080p, 10 GB of RAM": "швидка: 18,6 ГБ карти на 1080p, 10 ГБ ОЗП",
"the studio's own: 20 GB of a card at 1080p (16 of its blocks in RAM), 21 GB of RAM; 1440p fits too": "своє в студії: 20 ГБ карти на 1080p (16 її блоків в ОЗП), 21 ГБ ОЗП; 1440p теж вміщається",
"3B, 7B sharp and 7B": "3B, 7B sharp і 7B",
"SeedVR2 (ByteDance, Apache-2.0) as numz packs it: the Videographer's upscaler, a shot's video to 1080p or 1440p in one step, the details made anew. Measured on an RTX 3090, 107 frames of 768p: 3B to 1080p in 284 s, 7B sharp in 367 s, 7B sharp to 1440p in 592 s": "SeedVR2 (ByteDance, Apache-2.0) в упаковці numz: апскейлер Відеографа, відео кадру в 1080p або 1440p за один крок, деталі народжуються наново. Замір на RTX 3090, 107 кадрів 768p: 3B у 1080p за 284 с, 7B sharp за 367 с, 7B sharp у 1440p за 592 с",
