"Drag its corner to make it wider and taller; a double click here puts its size back": "Тягни за кут, щоб розтягти вшир і вгору; подвійний клік тут повертає розмір",
"No style": "Без стилю",
"No lyrics": "Без лірики",
"What the player in the rooms' footer and the window comparing takes stream: FLAC is the take itself, lossless (about 30 MB for a song of four minutes); Opus at 128 kbit/s is about 4 MB, made on the studio's machine the first time a take plays, for a slow line (a phone, a VPN). Everywhere else the studio hears and measures the lossless FLAC, and downloads stay WAV and FLAC.": "Що віддають сторінці плеєр у підвалі кімнат і вікно порівняння дублів: FLAC — сам дубль без втрат (близько 30 МБ на пісню в чотири хвилини); Opus 128 кбіт/с — близько 4 МБ, твориться на машині студії під час першого програвання дубля, для повільного зв'язку (телефон, VPN). У всіх інших місцях студія слухає й міряє FLAC без втрат, а завантаження лишаються WAV і FLAC.",
"Videographer · MiniMax H3": "Відеограф · MiniMax H3",
"All int8 tiers": "Усі рівні int8",
"the studio's own: a card of 24 GB and 64 GB of RAM": "своє в студії: карта 24 ГБ і 64 ГБ ОЗП",
"both modes whole and pruned, FastH3, ControlNet Union and the effects too": "обидва режими цілком і урізані, а ще FastH3, ControlNet Union та ефекти",
"unquantized, for cards of 80 GB; on 24 GB only streamed from RAM, slowly": "без квантування, для карт 80 ГБ; на 24 ГБ — лише потоком з ОЗП, повільно",
"MiniMax H3 (MiniMax) as Comfy-Org packs it: the Videographer's moving pictures, a shot at a time on a card of 24 GB, the shot's picture its first frame. Its licence (the MiniMax H3 Community License) does not allow running it on your own machines in the United States, the European Union, the United Kingdom or South Korea, and commercial use beyond the threshold it names needs MiniMax's own licence. Where you run it and what you make with it is yours to answer for: read the licence before you fetch it": "MiniMax H3 (MiniMax) в упаковці Comfy-Org: рухомі картинки Відеографа, по кадру на карті 24 ГБ, картинка кадру — його перший кадр. Його ліцензія (MiniMax H3 Community License) не дозволяє запускати його на своїх машинах у США, Євросоюзі, Великій Британії та Південній Кореї, а комерційне використання понад названий у ній поріг потребує окремої ліцензії MiniMax. Де ти його запускаєш і що твориш із ним — твоя відповідальність: прочитай ліцензію до завантаження",
"Shoot this shot with MiniMax H3: a draft (8 steps) or the final (28 steps); its picture, when it has one, is its first frame": "Зняти кадр MiniMax H3: чернетка (8 кроків) або чистовик (28 кроків); його картинка, якщо є, — перший кадр",
"Every shot with MiniMax H3 as a draft (8 steps), shot by shot on the free cards; a shot's picture, when it has one, is its first frame": "Усі кадри MiniMax H3 чернетками (8 кроків), кадр за кадром на вільних картах; картинка кадру, якщо є, — його перший кадр",
"Shoot all {0} shots with MiniMax H3 as drafts?\n\nOn the free cards, a few minutes a shot; the clip takes each shot's video as it comes.": "Зняти всі {0} кадрів MiniMax H3 чернетками?\n\nНа вільних картах, по кілька хвилин на кадр; кліп бере відео кожного кадру, щойно воно готове.",
"Shoot all": "Зняти всі",
