"Space plays, J K L, ← → a frame (Shift: a second), ↑ ↓ the edit points, A select, B blade, Ctrl+B cut, Delete joins, Ctrl+Z undoes": "Пробіл грає, J K L, ← → кадр (Shift: секунда), ↑ ↓ точки монтажу, A вибір, B лезо, Ctrl+B розріз, Delete склеює, Ctrl+Z скасовує",
