"Zoom in on the steps: half of them, around the middle. Or drag across a curve; Ctrl and the wheel zoom where the pointer is": "Збільшити за кроками: половина їх, довкола середини. Або протягніть мишею по кривій; Ctrl і коліщатко збільшують там, де вказівник",
"Zoom out: twice the steps": "Зменшити: удвічі більше кроків",
