"The player's stream": "Потік плеєра",
"What the player streams to the page: FLAC is the take itself, lossless (about 30 MB for a song of four minutes); Opus at 128 kbit/s is about 4 MB, made on the studio's machine the first time a take plays, for a slow line (a phone, a VPN). Downloads stay WAV and FLAC either way.": "Що плеєр віддає сторінці: FLAC — сам дубль без втрат (близько 30 МБ на пісню на чотири хвилини); Opus 128 кбіт/с — близько 4 МБ, створюється на машині студії під час першого відтворення дубля, для повільного зв'язку (телефон, VPN). Завантаження за будь-якого вибору лишається WAV і FLAC.",
