"Still": "Стоїть",
"Sung to the end? Whisper times the checked takes' lyrics one after another (on the processor, a minute or two each) and says, for each, whether its last lines were heard": "Доспівані до кінця? Whisper розмічає лірику позначених дублів один за одним (на процесорі, хвилина-дві на кожен) і каже про кожен, чи почуто останні рядки",
"Whisper listens to each in turn, on the processor: a minute or two a take": "Whisper слухає їх по черзі, на процесорі: хвилина-дві на дубль",
"Done: {0} sung to the end, {1} not, {2} could not say": "Готово: доспівані {0}, не доспівані {1}, не зрозуміти {2}",
"Whisper listens to {0} takes in turn, a minute or two each. Start?": "Whisper вислухає {0} дублів по черзі, хвилина-дві на кожен. Почати?",
"Checks": "Перевірки",
"Lines not heard at the end: {0}, after {1}. Suggested: the music written anew from there.": "Не почуто рядків у кінці: {0}, після {1}. Запропоновано: музика пишеться заново звідти.",
"Sung to the end?": "Доспівана до кінця?",
"Whisper listens to the take and times its lyrics line by line (on the processor, a minute or two): were its last lines sung?": "Whisper слухає дубль і розставляє час рядків лірики (на процесорі, хвилина-дві): чи проспівано останні рядки?",
"Whisper listens…": "Whisper слухає…",
"Every line heard; the last ends at {0}": "Усі рядки почуто; останній закінчується на {0}",
"Lines not heard at the end: {0}, after {1}": "Не почуто рядків у кінці: {0}, після {1}",
"Regenerate from {0}": "Перестворити з {0}",
"The timing heard too little of this take to say": "Таймінг почув у цьому дублі замало, щоб судити",
"The take did not open: Regenerate from… is in its card": "Дубль не відкрився: «Перестворити з…» є в його картці",
"Draw this shot's picture in the Artist: its prompt into the form, wide": "Намалювати картинку кадру в Художника: його промпт у форму, широкий формат",
"In the form: shot {0}'s picture, wide. Once drawn, give it to the shot from its slot in the Videographer": "У формі: картинка кадру {0}, широка. Коли намалюється, дай її кадру з його комірки у Відеографі",
"Clip": "Кліп",
"The clip cut from the shots' pictures in the song's time, each with a slow camera move as its scene's camera says; a shot without a picture of its own shows the take's cover, or its words and scene when the take has none. Made on the processor, no video model.": "Кліп із картинок кадрів у часі пісні: кожен кадр із повільним рухом камери, як сказано в його сцені; кадр без своєї картинки показує обкладинку дубля, а без обкладинки — свої слова й сцену. Створюється на процесорі, без відеомоделі.",
