"measured once a minute from now on": "відтепер міряється раз на хвилину",
"{0} free of {1}": "вільно {0} з {1}",
"A minute with the studio counts when a page played or was in your hands in it; however many pages, a minute is one. The takes from their meta.json; the machine once a minute, kept by the hour; the folders without what their links lead to elsewhere.": "Хвилина зі Студією зараховується, якщо сторінка в ній грала або була у тебе в руках; скільки б сторінок не було, хвилина одна. Дублі за їхнім meta.json; машина раз на хвилину, зберігається по годинах; теки без того, куди ведуть їхні посилання.",
"One click: back to the start of this take (at its start already: the take above). Two clicks within a second: the take above in the list": "Один клік: на початок цього дубля (якщо він уже на початку, то дубль вище). Два кліки за секунду: дубль вище у списку",
"Dislike: the take leaves the lists while «Show disliked takes in the lists» is off (Engine → Defaults); «Only the disliked» still finds it": "Не подобається: дубль зникає зі списків, поки вимкнено «Показувати дизлайкнуті дублі в списках» (Рушій → Типові); «Лише ті, що не сподобалися» його й далі знаходить",
"The player's buttons and texts at rest": "Кнопки й тексти плеєра у спокої",
"How solid the player's buttons, marks and times stand while the pointer is not on them; under the pointer they are always whole. The studio's own: 60 %": "Наскільки щільні кнопки, позначки й час плеєра, поки вказівник не на них; під вказівником вони завжди видні повністю. Студійне значення: 60 %",
