"Unprotect {0}? Its saves and the run itself can then be deleted.": "Зняти захист з {0}? Тоді його збереження і сам прогін можна буде видалити.",
"Protected: neither its saves nor the run itself can be deleted; ⋯ → Unprotect to change that": "Під захистом: ні збереження, ні сам прогін видалити не можна; ⋯ → Зняти захист, щоб це змінити",
