"{0} of them are in loras/, in the Creator's LoRAs. Take them out too (the space comes back), or keep them usable?": "З них у loras/, у LoRA Творця: {0}. Прибрати і їх (місце повернеться) чи залишити їх у вжитку?",
"{0} saves deleted, {1} back on the disk": "Видалено збережень: {0}, на диску звільнилося {1}",
