"Play only": "Грати лише",
"every take": "усі семпли",
"Only the takes with this mark play; the playlist keeps every take": "Грають лише семпли з цією позначкою; у плейлисті лишаються всі",
"Up next": "Далі",
"in {0} s": "за {0} с",
"Play it now": "Увімкнути зараз",
"Which quant the studio's writer runs: quality keeps the AutoRound 4 bits as they are (about 7.5 GB of VRAM), compact keeps those and lowers the rest (about 6.5 GB). Only those here can be chosen": "Який квант запускає власний Письменник: якість — 4 біти AutoRound як є (близько 7,5 ГБ відеопам'яті), компактний — ті самі 4 біти, решта нижче (близько 6,5 ГБ). Вибрати можна лише ті, що тут",
"Quality: the AutoRound 4 bits as they are (a 12 GB card)": "Якість: 4 біти AutoRound як є (карта на 12 ГБ)",
"Compact: for an 8 GB card": "Компактний: для карти на 8 ГБ",
"Not here yet: Engine → Models and LoRAs → Studio writer fetches it (6.7 GB; compact 5.5 GB).": "Поки його тут немає: Рушій → Моделі й LoRA → Письменник Студії завантажить його (6,7 ГБ; компактний 5,5 ГБ).",
"Its weights are here; llama.cpp's llama-server is not built yet: launcher/extras.sh builds it.": "Його ваги тут; llama-server з llama.cpp ще не зібраний: його збере launcher/extras.sh.",
"Qwopus3.5-9B-v3 (Jackrong's, on Qwen3.5-9B, Apache-2.0), quantized with AutoRound, through llama.cpp on this machine: nothing leaves it. It starts at the first question and leaves the card after 10 minutes without one.": "Qwopus3.5-9B-v3 (від Jackrong, на основі Qwen3.5-9B, Apache-2.0), квантована AutoRound, через llama.cpp на цій машині: нічого не йде назовні. Запускається на перше запитання і звільняє карту через 10 хвилин без запитань.",
"not here": "немає тут",
"llama-server not built": "llama-server не зібраний",
"asleep": "спить",
"on the processor": "на процесорі",
