"Studio writer": "Письменник Студії",
"Quality": "Якість",
"Compact": "Компактний",
"about 7.5 GB of VRAM with its 12K context: a 12 GB card": "близько 7,5 ГБ відеопам'яті з контекстом 12K: карта на 12 ГБ",
"about 6.5 GB of VRAM with its 12K context: an 8 GB card": "близько 6,5 ГБ відеопам'яті з контекстом 12K: карта на 8 ГБ",
"Qwopus3.5-9B-v3 (Jackrong's fine-tune of Qwen3.5-9B, Apache-2.0), quantized with AutoRound and moved into GGUF bit for bit, from goldhub/Ruach_Studio_Models_v2: the Writer's own language model on this machine, through llama.cpp (vendor/llama.cpp, built by launcher/extras.sh); Engine → Writer chooses between those here": "Qwopus3.5-9B-v3 (донавчання Qwen3.5-9B від Jackrong, Apache-2.0), квантована AutoRound і перенесена в GGUF біт у біт, з goldhub/Ruach_Studio_Models_v2: власна мовна модель Письменника на цій машині, через llama.cpp (vendor/llama.cpp, збирає launcher/extras.sh); Рушій → Письменник вибирає з тих, що тут",
"← → keys": "Клавіші ← →",
"Shift + ← →": "Shift + ← →",
"Start playing": "Починати грати",
"when its first minute is in and the rest will come in time": "коли прийшла перша хвилина і решта встигне прийти",
"when the whole take is in": "коли прийшов увесь дубль",
"On a slow line (a studio far away), a take can start before all of it has come: once its first minute is in and the rest will come before the playing reaches it; where it changes to the whole, it does so at a quiet moment. At home the whole comes within seconds, and it waits for it either way.": "На повільній лінії (студія далеко) дубль може почати грати до того, як прийде весь: щойно прийшла його перша хвилина і решта прийде раніше, ніж до неї дійде гра; там, де він змінюється цілим, це стається в тихому місці. Вдома ціле приходить за секунди, і він у будь-якому разі чекає на нього.",
"A click on a take plays it": "Клік по дублю його грає",
"New takes play when they are done": "Нові дублі грають, коли готові",
"A double-click on a card plays or stops it": "Подвійний клік по картці — грати або стоп",
